<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import {shanghaiDateKey,shanghaiDateTimeText} from '../../utils/shanghai-date.js';
import {validMobileDate,previousMobileDate} from '../../utils/mobile-finance-period.js';
import {useAuthStore} from '../../stores/auth.js';
import {canAccessPage,hasPermission} from '../../../../src/shared/permissions.js';
const router=useRouter(),route=useRoute(),auth=useAuthStore(),data=ref({metrics:{}}),loading=ref(false),error=ref('');
const today=shanghaiDateKey(),selectedDate=ref(validMobileDate(route.query.date,today)?String(route.query.date):today);
const yesterday=previousMobileDate(today),dayLabel=computed(()=>selectedDate.value===today?'今日':selectedDate.value===yesterday?'昨日':'所选日');
let generation=0,financeGeneration=0,timer=0,disposed=false,attempt=0,controller,financeController,dateNavigation=0,navigatingDate='';const financeError=ref('');const financeMetrics=ref({});
const fields=computed(()=>[
 ...(data.value.financial?[['today_profit',`${dayLabel.value}订单利润`,'money']]:[]),
 ['today_revenue',`${dayLabel.value}有效营业额`,'money'],['today_orders',`${dayLabel.value}有效订单`,'单'],['today_cancelled',`${dayLabel.value}取消`,'单'],['today_returns',`${dayLabel.value}退件`,'件'],['ad_roas','广告回报 ROAS','ratio'],['month_quantity','月累计销售件数','件'],['month_orders','月累计有效订单','单'],
 ...(data.value.financial?[['month_revenue','月累计营业额','money'],['month_profit','月累计订单利润','money'],['month_purchase_amount','月累计实际采购','money'],['month_ad_spend','月累计广告花费','money'],['inventory_total_value','当前库存占用（含在途）','money']]:[]),
 ['return_rate','月累计退货率','percent'],['cancel_rate','月累计取消率','percent']
]);
function display(key,type){const value=Object.hasOwn(financeMetrics.value,key)?financeMetrics.value[key]:data.value.metrics?.[key];if(value==null||value==='')return '—';const n=Number(value);if(!Number.isFinite(n))return '—';if(type==='percent')return `${(n*100).toFixed(1)}%`;if(type==='ratio')return n.toFixed(2);return `${type==='money'?'¥ ':''}${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:type==='money'?2:0}).format(n)}${['单','件'].includes(type)?` ${type}`:''}`;}
async function load(poll=false,date=selectedDate.value){const scope=currentApiCacheScope(),token=++generation;controller?.abort();controller=new AbortController();if(!poll){attempt=0;loading.value=true;}clearTimeout(timer);error.value='';try{const r=await apiClient.get(`/api/dashboard?view=mobile&date=${date}${poll?'&snapshotOnly=1':''}`,{noCache:true,signal:controller.signal});if(disposed||token!==generation||scope!==currentApiCacheScope()||date!==selectedDate.value)return;
 data.value={...r,metrics:{...data.value.metrics,...r.metrics}};
 if(r.snapshot?.status==='building'&&attempt++<60)timer=window.setTimeout(()=>load(true,date),2500);
 }catch(e){if(e.name!=='AbortError'&&token===generation&&scope===currentApiCacheScope())error.value=e.message;}finally{if(token===generation)loading.value=false;}}
async function loadFinance(date=selectedDate.value){if(!hasPermission(auth.user,'finance'))return;const scope=currentApiCacheScope(),token=++financeGeneration;financeController?.abort();financeController=new AbortController();financeError.value='';try{const r=await apiClient.get(`/api/dashboard?view=mobile-finance&date=${date}`,{noCache:true,signal:financeController.signal});if(!disposed&&token===financeGeneration&&scope===currentApiCacheScope()&&date===selectedDate.value)financeMetrics.value=r;}catch(e){if(e.name!=='AbortError'&&token===financeGeneration&&scope===currentApiCacheScope())financeError.value=e.message;}}
function refresh(){load();loadFinance();}
function resetScope(){++financeGeneration;financeController?.abort();financeMetrics.value={};financeError.value='';++generation;controller?.abort();clearTimeout(timer);data.value={metrics:{}};error.value='';loading.value=false;}
async function chooseDate(value){if(!validMobileDate(value,today)){error.value='请选择今天或更早的有效日期';return;}if(value===selectedDate.value)return;const navigation=++dateNavigation;navigatingDate=value;selectedDate.value=value;resetScope();await router.replace({query:{...route.query,date:value===today?undefined:value}});if(disposed||navigation!==dateNavigation)return;navigatingDate='';const actual=validMobileDate(route.query.date,today)?String(route.query.date):today;if(actual!==value)return;refresh();}
watch(()=>route.query.date,value=>{const date=validMobileDate(value,today)?String(value):today;if(navigatingDate&&date!==navigatingDate)return;if(date!==selectedDate.value){selectedDate.value=date;resetScope();refresh();}});
onMounted(()=>{refresh();window.addEventListener('erp:auth-scope-changed',resetScope);});onBeforeUnmount(()=>{disposed=true;resetScope();window.removeEventListener('erp:auth-scope-changed',resetScope);});
</script>
<template><div class="mobile-home-page">
 <div class="mobile-home-heading"><div><h1>经营概览</h1><small>{{selectedDate}} · 北京时间 · 金额人民币</small></div><el-button :loading="loading" @click="refresh()">刷新</el-button></div>
 <div class="mobile-home-date"><button type="button" :class="{active:selectedDate===today}" @click="chooseDate(today)">今天</button><button type="button" :class="{active:selectedDate===yesterday}" @click="chooseDate(yesterday)">昨天</button><input type="date" aria-label="经营日期" :value="selectedDate" :max="today" @change="chooseDate($event.target.value)"/></div>
 <p class="mobile-period-note">月累计：{{selectedDate.slice(0,7)}}-01 至 {{selectedDate}}；广告数据日：{{data.ad_date_key||'待返回'}}{{data.ad_date_key&&data.ad_date_key!==selectedDate?'（早于所选日）':''}}。</p>
 <button v-if="canAccessPage(auth.user,'/mobile/finance')" class="mobile-finance-entry" type="button" @click="router.push('/mobile/finance')"><span><strong>经营总览</strong><small>年度概况与各月账单</small></span><span aria-hidden="true">→</span></button>
 <el-alert v-if="financeError" :title="'采购和库存金额读取失败，可刷新重试：'+financeError" type="warning" :closable="false"/>
 <el-alert v-if="error" :title="error" type="warning" :closable="false"/>
 <p v-if="data.snapshot?.status==='building'" class="mobile-status">指标正在更新，已返回的数据先展示。</p>
 <section class="mobile-metric-grid"><article v-for="[key,label,type] in fields" :key="key" :class="{'is-key':key==='today_profit'||key==='today_revenue'}" :data-metric="key"><template v-if="key==='inventory_total_value'&&canAccessPage(auth.user,'/mobile/inventory-capital')"><button class="inventory-metric-link" @click="router.push('/mobile/inventory-capital')"><small>{{label}} · 查看明细 →</small><strong :title="display(key,type)">{{display(key,type)}}</strong></button></template><template v-else><small>{{label}}</small><strong :title="display(key,type)">{{display(key,type)}}</strong></template></article></section>
 <p v-if="data.financial" class="mobile-period-note">库存占用为当前快照，不代表所选日历史库存。{{financeMetrics.inventory_snapshot_at?`当前快照读取于 ${shanghaiDateTimeText(financeMetrics.inventory_snapshot_at)}`:''}}</p>

</div></template>
<style scoped>
.inventory-metric-link{display:grid;gap:9px;text-align:left;border:0;background:none;padding:0;color:inherit;font:inherit;cursor:pointer;min-width:0}
.mobile-home-date{display:flex;align-items:center;gap:8px}.mobile-home-date button{font:inherit;font-size:14px;border:1px solid var(--el-border-color);background:var(--el-bg-color);border-radius:8px;min-height:40px;padding:0 12px}.mobile-home-date button.active{color:var(--el-color-primary);border-color:var(--el-color-primary)}.mobile-home-date input{font:inherit;font-size:16px;min-width:0;flex:1;width:0;min-height:40px;box-sizing:border-box;border:1px solid var(--el-border-color);border-radius:8px;padding:0 8px;background:var(--el-bg-color);color:inherit}.mobile-period-note{margin:0;font-size:11px;line-height:1.6;color:var(--el-text-color-secondary)}.mobile-finance-entry{display:flex;justify-content:space-between;align-items:center;text-align:left;gap:12px;padding:12px;border:1px solid var(--el-color-primary-light-7);border-radius:12px;background:var(--el-color-primary-light-9);color:var(--el-color-primary);font:inherit}.mobile-finance-entry>span:first-child{display:grid;gap:5px}.mobile-finance-entry small{font-size:12px}
.mobile-home-page{display:grid;gap:12px}.mobile-home-heading{display:flex;justify-content:space-between;align-items:center;gap:8px}.mobile-home-heading h1{margin:0 0 5px;font-size:20px}.mobile-home-heading small,.mobile-status{color:var(--el-text-color-secondary);font-size:11px;line-height:1.5}.mobile-metric-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.mobile-metric-grid article{min-width:0;display:flex;flex-direction:column;justify-content:space-between;gap:10px;padding:13px 12px;border:1px solid var(--el-border-color-light);border-radius:12px;background:var(--el-bg-color);min-height:76px;box-sizing:border-box}.mobile-metric-grid article.is-key{background:var(--el-color-primary-light-9);border-color:var(--el-color-primary-light-7)}.mobile-metric-grid small{font-size:12px;color:var(--el-text-color-regular)}.mobile-metric-grid strong{font-size:clamp(17px,4.6vw,23px);line-height:1.2;font-weight:650;font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--el-text-color-primary)}.mobile-metric-grid .is-key strong{color:var(--el-color-primary)}@media(min-width:700px){.mobile-metric-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
</style>
